const money = (v: number | null | undefined) => Number.isFinite(v) ? `$${v!.toFixed(2)}` : "—";
const signedMoney = (v: number | null | undefined) => Number.isFinite(v) ? `${v! >= 0 ? "+" : "−"}$${Math.abs(v!).toFixed(2)}` : "—";
const probabilityLabel = (v: number | null | undefined) => Number.isFinite(v) ? `${((Math.abs(v!) <= 1 ? v! * 100 : v!)).toFixed(1)}%` : "—";
const compact = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const parsedTime = (value: string | number | null | undefined) => { if(value == null) return null; const time = typeof value === "number" ? value : Date.parse(value); return Number.isFinite(time) ? time : null };
const priceCents = (value: number | null | undefined) => Number.isFinite(value) ? Math.round(value! * 100) : null;
function ema(values: number[], period: number) { if(!values.length) return []; const k = 2 / (period + 1); const out = [values[0]]; for(let i = 1; i < values.length; i++)out.push(values[i] * k + out[i - 1] * (1 - k)); return out; }
function targetDateLabel(value: string | undefined, lang: "en" | "es") { if(!value) return "—"; const [y, m, d] = value.split("-").map(Number); return new Intl.DateTimeFormat(lang === "es" ? "es-US" : "en-US", { weekday: "long", year: "numeric", month: "long", day: "numeric", timeZone: "America/New_York" }).format(new Date(Date.UTC(y, m - 1, d, 12))) }
function etDateTime(value: number | string | null | undefined, lang: "en" | "es") { if(value == null) return "—"; const date = new Date(value); if(!Number.isFinite(date.getTime())) return "—"; return new Intl.DateTimeFormat(lang === "es" ? "es-US" : "en-US", { timeZone: "America/New_York", year: "numeric", month: "short", day: "numeric", hour: "numeric", minute: "2-digit", second: "2-digit", timeZoneName: "short" }).format(date) }
function etDateKey(value: number | string | null | undefined) { if(value == null) return null; const date = new Date(value); if(!Number.isFinite(date.getTime())) return null; const parts = Object.fromEntries(new Intl.DateTimeFormat("en-US", { timeZone: "America/New_York", year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(date).map(part => [part.type, part.value])); return `${parts.year}-${parts.month}-${parts.day}` }
function ApiStamp({ value, lang, label }: { value: number | string | null | undefined; lang: "en" | "es"; label: string }) { const date = value == null ? null : new Date(value); return <time className="api-stamp" dateTime={date && Number.isFinite(date.getTime()) ? date.toISOString() : undefined}>{label} · {etDateTime(value, lang)}</time> }
function marketProviderLabel(provider: string | null | undefined) { return provider === "alpaca_iex" ? "ALPACA IEX" : provider === "finnhub" ? "FINNHUB" : provider === "yahoo" ? "YAHOO FINANCE" : "MARKET FEED" }

function objectValue(value: unknown): value is Record<string, unknown> {
  return value != null && typeof value === "object" && !Array.isArray(value);
}

function selectedForecastPayload(value: unknown, targetDate: string): value is ForecastPayload {
  return objectValue(value) && value.targetDate === targetDate && Array.isArray(value.contributions) &&
    Array.isArray(value.feeds) && Array.isArray(value.events) && objectValue(value.adjustment);
}

function strictStatusPayload(value: unknown, targetDate: string): value is MooSystemStatus {
  return isMooSystemStatus(value, targetDate);
}

type MooSessionSelection = {
  date: string | null;
  mode: "FOLLOW_ACTIVE" | "AUDIT_PINNED";
};

function reconcileMooSessionSelection(selection: MooSessionSelection, nowMs: number): MooSessionSelection {
  if (selection.mode === "AUDIT_PINNED" && selection.date) return selection;
  return { date: defaultTargetSession(nowMs), mode: "FOLLOW_ACTIVE" };
}

function StrictStatusUnavailableNotice({ lang, message }: { lang: "en" | "es"; message: string }) {
  const spanish = lang === "es";
  return <>
    <div className="feed-alert" role="status">{message || (spanish
      ? "Cargando el estado MOO Estricto controlado por el servidor…"
      : "Loading the server-owned Strict MOO status…")}</div>
    <div className="strict-store-alert strict-empty-reasons" aria-label={spanish ? "Por qué los campos estrictos están vacíos" : "Why strict fields are empty"}>
      <strong>{spanish ? "POR QUÉ LOS CAMPOS ESTRICTOS ESTÁN VACÍOS" : "WHY STRICT FIELDS ARE EMPTY"}</strong>
      <span>{spanish
        ? "El estado actual del servidor aún no está disponible. La apertura predicha, la confianza, el modelo, la captura de variables y la orden congelada permanecen bloqueados; la investigación y el planificador simulado no pueden sustituirlos."
        : "Current server status is not yet available. Predicted open, confidence, model, feature snapshot, and frozen ticket remain blocked; research and the paper planner cannot substitute for them."}</span>
    </div>
  </>;
}

