function median(values: number[]) { const s = values.filter(Number.isFinite).sort((a, b) => a - b); if(!s.length) return 0; const m = Math.floor(s.length / 2); return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2 }
