        <details className="polymarket-evidence panel"><summary><div><span className="panel-kicker">{tx("Experimental crowd evidence", "Evidencia colectiva experimental")}</span><strong>Polymarket · {forecast?.polymarket?.status?.toUpperCase() ?? tx("NOT CONNECTED", "NO CONECTADO")} · {forecast?.polymarket?.signalState?.toUpperCase() ?? tx("NO SIGNAL", "SIN SEÑAL")}</strong></div><span>{polymarketMarkets.length} {tx("qualifying markets", "mercados relevantes")} · {tx("Range signal", "Señal de rango")} {forecast?.polymarket?.rangeSignal?.toFixed(2) ?? "0.00"} ＋</span></summary><div className="polymarket-body"><p>{forecast?.polymarket?.reason ?? tx("No qualifying Polymarket evidence is currently used in the NVDA opening estimate. Availability alone does not establish predictive value.", "Actualmente no se usa evidencia relevante de Polymarket en la estimación de apertura de NVDA. La disponibilidad por sí sola no establece valor predictivo.")}</p><div className="polymarket-meta"><ApiStamp value={forecast?.polymarket?.providerObservedAt} lang={lang} label={tx("Provider observation", "Observación del proveedor")} /><ApiStamp value={forecast?.polymarket?.checkedAt} lang={lang} label={tx("API checked", "API consultada")} /><span>{tx("Signed risk-off shock", "Impacto riesgo-off")}: {probabilityLabel(forecast?.polymarket?.signedRiskOffShock)}</span></div>{polymarketMarkets.length ? <div className="polymarket-grid">{polymarketMarkets.map((market, index) => { const used = polymarketApplied && forecast?.polymarket?.signalState === "active" && forecast.polymarket.primaryMarketId === market.id && Number(market.rangeSignal) > 0, mode: DisplayEffectMode = used ? "RANGE_ONLY" : "IGNORED", modeLabel = used ? tx("USED · RANGE ONLY", "USADO · SOLO RANGO") : tx("IGNORED", "IGNORADO"), observedAt = market.bookSnapshotAt ?? market.gammaUpdatedAt ?? market.checkedAt ?? forecast?.polymarket?.providerObservedAt; return <article className="polymarket-card" key={`${market.id}-${index}`}><div className="polymarket-card-head"><span className={`effect-badge effect-${mode.toLowerCase()}`}>{modeLabel}</span><ApiStamp value={observedAt} lang={lang} label={tx("Observed", "Observado")} /></div><span className="polymarket-topic">{market.topic}</span><h3>{market.question}</h3><dl><div><dt>{tx("Probability", "Probabilidad")}</dt><dd>{probabilityLabel(market.currentProbability)}</dd></div><div><dt>{tx("Since prior close", "Desde cierre previo")}</dt><dd>{Number.isFinite(market.probabilityShock) ? `${market.probabilityShock! >= 0 ? "+" : ""}${probabilityLabel(market.probabilityShock)}` : "—"}</dd></div><div><dt>{tx("Liquidity", "Liquidez")}</dt><dd>{Number.isFinite(market.liquidity) ? `$${compact.format(market.liquidity!)}` : "—"}</dd></div><div><dt>{tx("Spread", "Diferencial")}</dt><dd>{probabilityLabel(market.spread)}</dd></div><div><dt>{tx("Risk-off shock", "Impacto riesgo-off")}</dt><dd>{probabilityLabel(market.signedRiskOffShock)}</dd></div><div><dt>{tx("Range signal", "Señal de rango")}</dt><dd>{Number.isFinite(market.rangeSignal) ? market.rangeSignal!.toFixed(2) : "—"}</dd></div></dl><p>{used ? tx("This qualifying repricing is used to widen uncertainty only; it does not move the NVDA central estimate.", "Esta variación relevante solo amplía la incertidumbre; no mueve la estimación central de NVDA.") : tx("Visible for evidence review, but it contributes zero to the current estimate.", "Visible para revisar evidencia, pero aporta cero a la estimación actual.")}</p>{market.url ? <a href={market.url} target="_blank" rel="noreferrer">{tx("Open source market", "Abrir mercado fuente")} ↗</a> : null}</article> })}</div> : <div className="polymarket-empty">{tx("No qualifying market — no forecast adjustment.", "Sin mercado relevante — sin ajuste del pronóstico.")}</div>}</div></details>
